using System.Text.Json;
using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings() =>
        JsonSerializer.Serialize(new
        {
            AppName = "ConfigMcpServer",
            Version = "1.0.0",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        }, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(UriTemplate = "config://app/env", Name = "Environment Info",
        MimeType = "application/json"),
     Description("Returns runtime environment details.")]
    public static string GetEnvironmentInfo() =>
        JsonSerializer.Serialize(new
        {
            MachineName = Environment.MachineName,
            OsVersion = Environment.OSVersion.ToString(),
            DotNetVersion = Environment.Version.ToString(),
            ProcessorCount = Environment.ProcessorCount
        }, new JsonSerializerOptions { WriteIndented = true });
}

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Looks up a configuration value by key name.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g., 'MaxRetries', 'AppName')")] string key)
    {
        var config = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["AppName"] = "ConfigMcpServer",
            ["Version"] = "1.0.0",
            ["MaxRetries"] = "3",
            ["TimeoutSeconds"] = "30"
        };

        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Unknown configuration key: '{key}'. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("Lists all available configuration keys.")]
    public static string ListConfigKeys() =>
        string.Join("\n", new[] { "AppName", "Version", "MaxRetries", "TimeoutSeconds" });
}

